-- READ-ONLY verification of the read posture and scope drift of supabase_read_only_user. Generated by tools/intelligence/ro_scope.py. Expected value is on each row.
with permitted(name) as (values ('alert_sources'), ('alerts'), ('alerts_tz_backfill_backup_20261106'), ('backup_aemo_after_now_20261123'), ('backup_aemo_published_at_20261123'), ('backup_rss_published_at_20261124'), ('backup_source_registry_retire_20261123'), ('backup_twilio_published_at_20261123'), ('brief_lessons_learned'), ('captains_daily_briefs'), ('content_signals'), ('domain_heartbeat_latest'), ('domain_heartbeats'), ('domain_heartbeats_latest'), ('domain_registry'), ('downdetector_baseline_history'), ('downdetector_learned_thresholds'), ('emergency_alert_feed_state'), ('emergency_alert_source_integrity'), ('emergency_alert_summary_state'), ('external_fetch_usage'), ('intelligence_briefs'), ('intelligence_event_validation'), ('intelligence_events'), ('intelligence_ingestion_quality_daily'), ('intelligence_source_health'), ('intelligence_source_health_latest'), ('intelligence_source_registry'), ('llm_call_metrics'), ('llm_daily_costs'), ('llm_usage_by_model_30d'), ('llm_usage_daily_totals_14d'), ('ori_sector_activity'), ('ori_source_documents'), ('ori_theme_frequency'), ('ori_watch_items'), ('signal_corroboration'), ('signal_escalation_history'), ('source_registry_by_tier'), ('source_reliability_snapshot'), ('system_heartbeat'), ('validation_job_runs'), ('watchlist_items'), ('watchlist_tracking')),
col_limited(name) as (values ('captains_daily_briefs'), ('llm_call_metrics')),
public_rels as (select c.oid, c.relname from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind in ('r','v','m','p'))
select 'member_of_pg_read_all_data (platform-managed; table scope is application-level)' as check, pg_has_role('supabase_read_only_user', 'pg_read_all_data', 'member')::text as value, 'true (cannot be revoked by postgres); if false the scope is now database-enforced' as expected
union all
select 'member_of_pg_monitor (pg_stat_statements / pg_stat_activity text readable; the guard refuses those names)', pg_has_role('supabase_read_only_user', 'pg_monitor', 'member')::text, 'true today' 
union all
select 'default_transaction_read_only', coalesce((select array_to_string(s.setconfig, ';') from pg_db_role_setting s where s.setrole = 'supabase_read_only_user'::regrole), '(none)'), 'default_transaction_read_only=on'
union all
select 'relations_not_in_scope_lists_(new_since_last_review)', coalesce(string_agg(r.relname, ', ' order by r.relname), '(none)'), '(none): add to all_public_relations in supabase_ro_scope.json and decide permitted or not'
from public_rels r
where r.relname <> all (array['activity_logs', 'advisory_sessions', 'agent_performance', 'alert_silences', 'alert_sites', 'alert_sources', 'alerts', 'alerts_tz_backfill_backup_20261106', 'analytics_health_daily', 'architecture_records', 'audit_events', 'authority_audit_log', 'backup_aemo_after_now_20261123', 'backup_aemo_published_at_20261123', 'backup_rss_published_at_20261124', 'backup_source_registry_retire_20261123', 'backup_twilio_published_at_20261123', 'batch_jobs', 'bot_rate_limits', 'brief_lessons_learned', 'build_request_inbox', 'burnout_profile', 'capabilities', 'capacity_calibration', 'capacity_calibration_summary', 'capacity_checkins', 'capacity_checkins_today', 'capacity_experiments', 'capacity_intervention_events', 'capacity_interventions', 'capacity_preferences', 'capacity_protocol_steps', 'capacity_rescue_protocols', 'captain_readiness_history', 'captains_daily_briefs', 'captains_log_entries', 'captured_items', 'command_memory_records', 'commander_decisions', 'commander_events', 'commander_memory_events', 'commander_mission_candidates', 'comms_content', 'comms_content_revisions', 'comms_pipeline', 'comms_portfolio', 'content_pipeline_summary', 'content_signals', 'conversation_turns', 'core_events', 'daily_health_snapshot', 'debrief_logs', 'debrief_sessions', 'debrief_turns', 'decide_ledger', 'decision_records', 'decisions', 'dispatch_health', 'document_chunks', 'domain_heartbeat_latest', 'domain_heartbeats', 'domain_heartbeats_latest', 'domain_registry', 'downdetector_baseline_history', 'downdetector_learned_thresholds', 'emergency_alert_feed_state', 'emergency_alert_source_integrity', 'emergency_alert_summary_state', 'escalation_events', 'escalation_history', 'external_fetch_usage', 'follow_through_events', 'follow_through_sends', 'google_calendar_tokens', 'health_adverse_events', 'health_daily_logs', 'health_events', 'health_ingestion_quality_daily', 'health_insights', 'health_signal_corroboration', 'health_signal_validation', 'health_signals', 'health_source_articles', 'health_source_fetch_config', 'health_source_registry', 'home_sessions', 'human_systems_daily', 'human_systems_feedback', 'human_systems_friction', 'human_systems_patterns', 'human_systems_recommendations', 'insight_outcomes', 'intelligence_briefs', 'intelligence_event_validation', 'intelligence_events', 'intelligence_health_correlations', 'intelligence_ingestion_quality_daily', 'intelligence_notes', 'intelligence_source_health', 'intelligence_source_health_latest', 'intelligence_source_registry', 'knowledge_documents', 'knowledge_edges', 'knowledge_hierarchy_summary', 'knowledge_nodes', 'knowledge_unmapped_missions', 'lessons_learned', 'llm_call_metrics', 'llm_cost_governance', 'llm_daily_costs', 'llm_usage_by_model_30d', 'llm_usage_daily_totals_14d', 'mission_delivery', 'mission_delivery_metrics', 'mission_execution_events', 'mission_state_transitions', 'missions', 'mood_chart', 'mood_chart_7d', 'mood_chart_today', 'number_one_context', 'officer_clearances', 'operational_patterns', 'ori_sector_activity', 'ori_source_documents', 'ori_theme_frequency', 'ori_watch_items', 'outcome_records', 'pain_recovery_consents', 'pain_recovery_events', 'pain_recovery_model_interactions', 'pain_recovery_recipe_ingredients', 'pain_recovery_reviews', 'pain_recovery_sessions', 'personal_tasks', 'pgqueuer', 'pgqueuer_log', 'pgqueuer_schedules', 'pgqueuer_statistics', 'physical_exercises', 'physical_readiness_checkins', 'physical_readiness_profiles', 'physical_workout_exercise_logs', 'physical_workout_sessions', 'processing_chunks', 'processing_documents', 'recommendation_effectiveness', 'recovery_confidence_today', 'recovery_pulse_adherence_7d', 'recovery_pulses', 'recovery_pulses_daily', 'research_memory', 'research_metrics', 'retrieval_logs', 'shopping_list_items', 'shopping_list_saved_views', 'signal_corroboration', 'signal_escalation_history', 'source_registry_by_tier', 'source_reliability_snapshot', 'specialist_permissions', 'specialists', 'staff_autonomy_log', 'strategic_objective_progress', 'strategic_objectives', 'strategic_orphan_missions', 'system_heartbeat', 'task_events', 'tasks', 'user_settings', 'validation_job_runs', 'verification_state', 'watchlist_items', 'watchlist_tracking', 'weekly_reviews', 'weight_logs', 'wellness_reminder_log', 'working_memory'])
union all
select 'direct_write_privileges', count(*)::text, '0'
from information_schema.role_table_grants g where g.grantee = 'supabase_read_only_user' and g.privilege_type in ('INSERT','UPDATE','DELETE','TRUNCATE')
union all
select 'schemas_it_can_create_in', count(*)::text, '0'
from pg_namespace n where has_schema_privilege('supabase_read_only_user', n.oid, 'create') and n.nspname not like 'pg_%' and n.nspname <> 'information_schema'
union all
-- a SECURITY DEFINER function it can execute would run with its owner's rights and could read or write outside this scope
select 'secdef_functions_executable_non_system', coalesce(string_agg(n.nspname || '.' || p.proname, ', '), '(none)'), '(none)'
from pg_proc p join pg_namespace n on n.oid = p.pronamespace
where p.prosecdef and n.nspname not in ('pg_catalog','information_schema') and has_function_privilege('supabase_read_only_user', p.oid, 'execute')
union all
-- a view runs with its OWNER's privileges: every permitted view must depend only on permitted relations
select 'permitted_views_depending_on_unpermitted_relations',
  coalesce(string_agg(distinct v.relname || ' -> ' || d.relname, ', '), '(none)'), '(none)'
from pg_class v join permitted p on p.name = v.relname and v.relnamespace = 'public'::regnamespace and v.relkind in ('v','m')
join pg_rewrite rw on rw.ev_class = v.oid
join pg_depend dep on dep.objid = rw.oid and dep.classid = 'pg_rewrite'::regclass and dep.refclassid = 'pg_class'::regclass
join pg_class d on d.oid = dep.refobjid and d.relnamespace = 'public'::regnamespace and d.oid <> v.oid
where d.relname not in (select name from permitted);
